// Browser-safe canonical import contract. No file or network access.
import {validateMesh} from './geometry.js';
import {meshDigest,sha256,COMPILER_VERSION} from './digest.js';
import {resolveMaterial} from './materials.js';
import {add,ry} from '../visual/vectors.js';
export const IMPORT_PROFILE='foundry-af05',IMPORT_ID='imported-mesh';
export const IMPORT_LIMITS=Object.freeze({parts:64,vertices:100000,triangles:100000,pixels:1048576,serialized:12*1024*1024,files:32,sourceBytes:16*1024*1024});
const fail=m=>{throw Error('import: '+m)};
export function strict(o,keys){if(!o||typeof o!=='object'||Array.isArray(o)||![Object.prototype,null].includes(Object.getPrototypeOf(o)))fail('object required');for(const k of Object.keys(o))if(!keys.includes(k))fail('unknown field '+k);return o}
export function finite(v,a=-1000,b=1000){if(typeof v!=='number'||!Number.isFinite(v)||v<a||v>b)fail('numeric bounds');return v}
export function int(v,a,b){if(!Number.isSafeInteger(v)||v<a||v>b)fail('integer bounds');return v}
export const hex=x=>typeof x==='string'&&/^[0-9a-f]{64}$/.test(x);
const txt=(s,max)=>{if(typeof s!=='string'||!s.trim()||s.length>max||/[\u0000-\u001f\u007f]/.test(s))fail('invalid provenance text');return s};
export const compatibleLicenses=Object.freeze(['CC0-1.0','CC-BY-4.0','MIT','Apache-2.0','LicenseRef-Original']);
export function provenance(p){strict(p,['creator','source','sourceVersion','license','licenseReference','attribution','modified','commercialUse','redistribution']);for(const [k,n] of [['creator',256],['source',512],['sourceVersion',128],['license',128],['licenseReference',2048],['attribution',1024]])txt(p[k],n);for(const k of ['modified','commercialUse','redistribution'])if(typeof p[k]!=='boolean')fail('provenance boolean');return {...p,status:compatibleLicenses.includes(p.license)&&p.commercialUse&&p.redistribution?'eligible':'quarantined'}}
const ascii=s=>new TextEncoder().encode(s);
export const bundleDigest=b=>sha256(ascii(JSON.stringify(b)));
export const encodeMesh=m=>({positions:Array.from(m.positions),normals:Array.from(m.normals),uvs:Array.from(m.uvs),indices:Array.from(m.indices),topology:m.topology});
export function decodeMesh(m){strict(m,['positions','normals','uvs','indices','topology']);for(const [k,max] of [['positions',IMPORT_LIMITS.vertices*3],['normals',IMPORT_LIMITS.vertices*3],['uvs',IMPORT_LIMITS.vertices*2],['indices',IMPORT_LIMITS.triangles*3]])if(!Array.isArray(m[k])||m[k].length>max)fail('mesh array budget');for(const k of ['positions','normals','uvs'])for(const x of m[k])finite(x,-1000,1000);for(const x of m.indices)int(x,0,IMPORT_LIMITS.vertices-1);const out={positions:Float32Array.from(m.positions),normals:Float32Array.from(m.normals),uvs:Float32Array.from(m.uvs),indices:Uint32Array.from(m.indices),topology:m.topology,groups:[{start:0,count:m.indices.length,material:0}]};validateMesh(out);return out}
export function makeBundle({format,provenance:raw,files,parts,normalization}){const p=provenance(raw),body={version:1,format,provenance:p,files,normalization,parts};return {...body,digest:bundleDigest(body)}}
const cache=new WeakMap();
export function compileBundle(b){strict(b,['version','format','provenance','files','normalization','parts','digest']);if(b.version!==1||!['glb','gltf','obj','svg','png'].includes(b.format)||!hex(b.digest))fail('bundle header');const serialized=JSON.stringify(b);if(serialized.length>IMPORT_LIMITS.serialized)fail('bundle size');const prior=cache.get(b);if(prior?.serialized===serialized)return prior.result;
 const {digest,...body}=b;if(bundleDigest(body)!==digest)fail('bundle digest mismatch');const {status,...p}=b.provenance;if(status!=='eligible'||provenance(p).status!=='eligible')fail('quarantined license');if(!Array.isArray(b.files)||b.files.length<1||b.files.length>IMPORT_LIMITS.files)fail('source file inventory');let sourceBytes=0;const names=new Set();for(const file of b.files){strict(file,['name','sha256','bytes']);txt(file.name,256);if(names.has(file.name)||!hex(file.sha256))fail('source digest');names.add(file.name);sourceBytes+=int(file.bytes,1,IMPORT_LIMITS.sourceBytes)}if(sourceBytes>IMPORT_LIMITS.sourceBytes)fail('source byte budget');
 strict(b.normalization,['sourceUp','metersPerUnit','scale','offset','targetHeight']);if(!['Y','Z'].includes(b.normalization.sourceUp))fail('source axis');for(const k of ['metersPerUnit','scale','targetHeight'])finite(b.normalization[k],1e-8,1000);if(!Array.isArray(b.normalization.offset)||b.normalization.offset.length!==3)fail('normalization offset');b.normalization.offset.forEach(x=>finite(x));
 if(!Array.isArray(b.parts)||!b.parts.length||b.parts.length>IMPORT_LIMITS.parts)fail('part budget');let vertices=0,triangles=0,pixels=0;const textures=new Map(),ids=new Set(),lo=[Infinity,Infinity,Infinity],hi=[-Infinity,-Infinity,-Infinity];
 const parts=b.parts.map(part=>{strict(part,['id','mesh','material','image']);if(typeof part.id!=='string'||!/^[a-z0-9-]{1,48}$/.test(part.id)||ids.has(part.id))fail('part ID');ids.add(part.id);const mesh=decodeMesh(part.mesh),s=validateMesh(mesh);vertices+=s.vertices;triangles+=s.triangles;if(vertices>IMPORT_LIMITS.vertices||triangles>IMPORT_LIMITS.triangles)fail('aggregate geometry budget');for(let k=0;k<3;k++){lo[k]=Math.min(lo[k],s.bounds.min[k]);hi[k]=Math.max(hi[k],s.bounds.max[k])}const surface=resolveMaterial(part.material,'cpu');delete surface.texture;let image=null;
 if(part.image){const im=part.image;strict(im,['width','height','rgba','digest']);const w=int(im.width,1,1024),h=int(im.height,1,1024);if(!Array.isArray(im.rgba)||im.rgba.length!==w*h*4||!hex(im.digest))fail('image size');if(w*h>IMPORT_LIMITS.pixels)fail('image pixels');for(let i=0;i<im.rgba.length;i++){int(im.rgba[i],0,255);if(i%4===3&&im.rgba[i]!==255)fail('only opaque imported PNG supported')}const rgba=Uint8Array.from(im.rgba);if(sha256(rgba)!==im.digest)fail('image digest');const key=w+'x'+h+':'+im.digest;if(!textures.has(key)){pixels+=w*h;if(pixels>IMPORT_LIMITS.pixels)fail('aggregate image budget');textures.set(key,{width:w,height:h,rgba,digest:key})}image=textures.get(key)}
 const hash=meshDigest(mesh);return {id:part.id,mesh,surface,image,hash,bytes:mesh.positions.byteLength+mesh.normals.byteLength+mesh.uvs.byteLength+mesh.indices.byteLength}});
 if(Math.abs(lo[1])>1e-4||Math.max(...hi.map((v,i)=>v-lo[i]))>10)fail('normalized bounds');const result={parts,lo,hi,digest,triangles,vertices,pixels};cache.set(b,{serialized,result});return result
}
const identity=[[1,0,0],[0,1,0],[0,0,1]];
function tf(pose){return {point:p=>add(ry(p.map(v=>v*pose.scale),pose.yaw),pose.origin),vector:p=>ry(p.map(v=>v*pose.scale),pose.yaw)}}
export function importedCommands(asset){const b=compileBundle(asset.importBundle),t=tf(asset.pose);return b.parts.map(p=>({id:asset.id+'/'+p.id,mesh:p.mesh,meshRef:p.hash,meshKey:COMPILER_VERSION+':'+p.hash,geometryBytes:p.bytes,origin:t.point([0,0,0]),axes:identity.map(t.vector),pivot:asset.pose.origin,materialSlot:p.id,color:p.surface.baseColor,emissive:p.surface.emissiveIntensity>0,surface:p.surface,...(p.image?{importTexture:p.image}:{}),lod:0}))}
export function importedBounds(asset){const b=compileBundle(asset.importBundle),t=tf(asset.pose),lo=[Infinity,Infinity,Infinity],hi=[-Infinity,-Infinity,-Infinity];for(const x of [b.lo[0],b.hi[0]])for(const y of [b.lo[1],b.hi[1]])for(const z of [b.lo[2],b.hi[2]])t.point([x,y,z]).forEach((v,i)=>{lo[i]=Math.min(lo[i],v);hi[i]=Math.max(hi[i],v)});return {lo,hi,center:lo.map((v,i)=>(v+hi[i])/2)}}
export function sampleImported(image,u,v){const x=(u-Math.floor(u))*(image.width-1),y=(1-(v-Math.floor(v)))*(image.height-1),ix=Math.floor(x),iy=Math.floor(y),dx=x-ix,dy=y-iy,a=(iy*image.width+ix)*4,b=(Math.min(iy+1,image.height-1)*image.width+ix)*4,k=Math.min(1,image.width-1-ix)*4;return [0,1,2].map(j=>((image.rgba[a+j]*(1-dx)+image.rgba[a+k+j]*dx)*(1-dy)+(image.rgba[b+j]*(1-dx)+image.rgba[b+k+j]*dx)*dy)/255)}
